xiv.org/pdf/2609.17325", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2609.17325", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2609.17325", "pdf_url": "https://arxiv.org/pdf/2609.17325", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Biological cells can be viewed as individual, interacting agents whose collective dynamics give rise to adaptive behaviour at multiple levels of organisation, from individual cells through tissues to whole multicellular organisms. In this perspective and tutorial article we discuss whether intrinsic rewards in artificial neural systems can support adaptation, functional specialisation and higher-level self-organisation without a shared external objective. We review empowerment, curiosity, learning progress, information gain, unsupervised skill discovery, mutual information estimation and the use of world models for intrinsic reward computation. Particular attention is given to failure modes showing when such objectives do not produce sustained exploration or increasingly complex behaviour. We argue that more capable systems may require complementary objectives, communication, memory, learning at multiple temporal scales and environmental constraints. Based on this perspective, we outline three experimental directions. These include a resource-constrained environment in which otherwise stable behavioural attractors become unsustainable, allowing us to test whether environmental constraints can mitigate characteristic failure modes of intrinsic objectives. The network of recurrent agents with per-agent intrinsic rewards, and a hierarchical world-model agent in which exploratory motor competence develops before goal-directed behaviour. These experiments are intended to test whether intrinsic learning can lead to adaptive organisation at progressively higher levels."}]", "excerpt_truncated": true, "source_sha256": "651b1d9d61ef8ca6458afc9ac36b4d17cb963c70d886e710544b8abf14339b5a", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1111/1751-7915.14222", "openalex:W4320709689", "arxiv:2609.17325"], "source_candidates": ["https://doi.org/10.1111/1751-7915.14222", "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/1751-7915.14222", "https://arxiv.org/abs/2609.17325", "https://arxiv.org/pdf/2609.17325"], "source_candidate_identities": {}}
